,"display_order":10},{"storage_path":"vehicles/volkswagen-golf-1-4-tsi-2011/volkswagen-golf-1-4-tsi-2011-cockpit.jpg","alt_text":"Volkswagen Golf 1.4 TSI 122PK foto 12","is_featured":false,"display_order":11}]},{"slug":"volkswagen-golf-6-tsi-1-2-zwart","title":"Volkswagen Golf 6 TSI 1.2","brand":"Volkswagen","model":"Golf 6 TSI 1.2","year":2012,"price":5400,"mileage":167450,"fuel_type":"Benzine","engine":"1.197 TSI 85PK","transmission":"Handgeschakeld","euro_norm":"Euro 5","seats":5,"description":"","status":"available","is_visible":true,"display_order":9,"features":["Trekhaak","Airco","Parkeersensor","Boordcomputer"],"images":[{"storage_path":"vehicles/volkswagen-golf-6-tsi-1-2-zwart/volkswagen-golf-6-tsi-1-2-zwart-exterieur-voor.jpg","alt_text":"Volkswagen Golf 6 TSI 1.2 foto 1","is_featured":true,"display_order":0},{"storage_path":"vehicles/volkswagen-golf-6-tsi-1-2-zwart/volkswagen-golf-6-tsi-1-2-zwart-exterieur-zij.jpg","alt_text":"Volkswagen Golf 6 TSI 1.2 foto 2","is_featured":false,"display_order":1},{"storage_path":"vehicles/volkswagen-golf-6-tsi-1-2-zwart/volkswagen-golf-6-tsi-1-2-zwart-exterieur-achter.jpg","alt_text":"Volkswagen Golf 6 TSI 1.2 foto 3","is_featured":false,"display_order":2},{"storage_path":"vehicles/volkswagen-golf-6-tsi-1-2-zwart/volkswagen-golf-6-tsi-1-2-zwart-interieur-dashboard.jpg","alt_text":"Volkswagen Golf 6 TSI 1.2 foto 4","is_featured":false,"display_order":3},{"storage_path":"vehicles/volkswagen-golf-6-tsi-1-2-zwart/volkswagen-golf-6-tsi-1-2-zwart-interieur-stoelen.jpg","alt_text":"Volkswagen Golf 6 TSI 1.2 foto 5","is_featured":false,"display_order":4},{"storage_path":"vehicles/volkswagen-golf-6-tsi-1-2-zwart/volkswagen-golf-6-tsi-1-2-zwart-motor.jpg","alt_text":"Volkswagen Golf 6 TSI 1.2 foto 6","is_featured":false,"display_order":5},{"storage_path":"vehicles/volkswagen-golf-6-tsi-1-2-zwart/volkswagen-golf-6-tsi-1-2-zwart-kofferruimte.jpg","alt_text":"Volkswagen Golf 6 TSI 1.2 foto 7","is_featured":false,"display_order":6},{"storage_path":"vehicles/volkswagen-golf-6-tsi-1-2-zwart/volkswagen-golf-6-tsi-1-2-zwart-trekhaak.jpg","alt_text":"Volkswagen Golf 6 TSI 1.2 foto 8","is_featured":false,"display_order":7},{"storage_path":"vehicles/volkswagen-golf-6-tsi-1-2-zwart/volkswagen-golf-6-tsi-1-2-zwart-velgen.jpg","alt_text":"Volkswagen Golf 6 TSI 1.2 foto 9","is_featured":false,"display_order":8}]}]'::jsonb) loop
    insert into public.vehicles (slug, title, brand, model, year, price, mileage, fuel_type, engine, transmission, euro_norm, seats, description, status, is_visible, display_order)
    values (
      item->>'slug', item->>'title', item->>'brand', item->>'model',
      nullif(item->>'year', '')::integer,
      nullif(item->>'price', '')::integer,
      nullif(item->>'mileage', '')::integer,
      item->>'fuel_type', item->>'engine', item->>'transmission', item->>'euro_norm',
      nullif(item->>'seats', '')::integer,
      coalesce(item->>'description', ''),
      item->>'status',
      coalesce((item->>'is_visible')::boolean, true),
      (item->>'display_order')::integer
    )
    on conflict (slug) do update set
      title = excluded.title, brand = excluded.brand, model = excluded.model, year = excluded.year,
      price = excluded.price, mileage = excluded.mileage, fuel_type = excluded.fuel_type,
      engine = excluded.engine, transmission = excluded.transmission, euro_norm = excluded.euro_norm,
      seats = excluded.seats, description = excluded.description, status = excluded.status,
      is_visible = excluded.is_visible, display_order = excluded.display_order, updated_at = now()
    returning id into vehicle_uuid;

    delete from public.vehicle_features where vehicle_id = vehicle_uuid;
    feature_index := 0;
    for feature_text in select jsonb_array_elements_text(item->'features') loop
      insert into public.vehicle_features (vehicle_id, label, display_order)
      values (vehicle_uuid, feature_text, feature_index);
      feature_index := feature_index + 1;
    end loop;

    delete from public.vehicle_images where vehicle_id = vehicle_uuid;
    for image_item in select * from jsonb_array_elements(item->'images') loop
      insert into public.vehicle_images (vehicle_id, storage_path, alt_text, is_featured, display_order)
      values (
        vehicle_uuid,
        image_item->>'storage_path',
        image_item->>'alt_text',
        coalesce((image_item->>'is_featured')::boolean, false),
        (image_item->>'display_order')::integer
      );
    end loop;
  end loop;
end $$;
